mapper.select:
SELECT homepage_id, facility_idx, facility_name, facility_desc, use_date, start_time, end_time, limit_count, apply_start_date, apply_end_date, apply_start_time, apply_end_time, use_yn, delete_yn, add_date, add_id, modify_date, modify_id, date_type, (SELECT COUNT(*) FROM FACILITY_REQ WHERE homepage_id = a.homepage_id AND facility_idx = a.facility_idx AND delete_yn = 'N' AND apply_status != '3') AS apply_count, CASE WHEN SYSDATE BETWEEN TO_DATE(a.apply_start_date || ' ' || a.apply_start_time, 'YYYY-MM-DD HH24:mi') AND TO_DATE(a.apply_end_date || ' ' || a.apply_end_time, 'YYYY-MM-DD HH24:mi') THEN 'Y' WHEN TO_CHAR(SYSDATE, 'YYYY-MM-DD') > use_date THEN 'N' ELSE 'N' END AS apply_yn FROM FACILITY_MANAGE a WHERE homepage_id = #{homepage_id}
AND date_type = #{date_type}
AND delete_yn = 'N' AND USE_YN = 'Y' AND use_date LIKE #{plan_date}||'%' ORDER BY use_date
